// TH14 synthetic appearance aliases (see transcribe/th14/bullet-types.md).
// Source type15 (INVERT_RICE) and type8 (RICE) both map to the same target number;
// base radius 2.4px, colors 0..15.
const TH14_RICE: int = 480;
const TH14_INVERT_RICE: int = 592;

// TH14 v1.00b st05bs::Boss3, entry source lines 331-390; attack helpers 392-480.
// Source T0 is the timerReset at line 340. Real timer 2100; shells adds 120 opening
// buffer and 500 tail frames (TIME_LIMIT = 120 + 2100 + 500 + 4 startup margin).
// Entry anchor (0,144) is the previous attack's fixed move target (BossCard2:648).
const TIME_LIMIT: int = 2724;
const SOURCE_LIMIT: int = 2100;
const OPENING_BUFFER: int = 120;

// Source etEx records (async=0): ANIM(2,a1) -> VELTIME(0x200000,a30,r1.0) ->
// SETSPRITE(type8) -> PLAYSOUND38 -> VELTIME(a50,r3.0) -> SETSPRITE(type15) ->
// PLAYSOUND39 -> VELTIME(a60,r0.5). Direction stays fixed (s=-999999), so the
// target scalar step_speed matches the source scalar ramp. The birth ANIM retreat
// -4*2px is kept with sh_dist; other birth animation and both sounds are omitted.
// set_shape keeps the per-task color and both source types share radius 2.4.
xformdef CARD_EX {
    @30 step_speed(1fx, 30);
    set_shape(TH14_RICE);
    @50 step_speed(3fx, 50);
    set_shape(TH14_INVERT_RICE);
    @60 step_speed(0.5fx, 60);
}

sub emit_ring(color: int, n: int) {
    // Boss3_at/Boss3_at2: etSprite(0/1,15,color), etAim mode3 ring, etCount(N,1),
    // etSpeed(2,1). The configured etAngle delta is overwritten before the first
    // etOn, so every volley is a plain N-way ring; etDist is always 0.
    sh_reset(0);
    sh_sprite(0, TH14_INVERT_RICE, color);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, -8fx);
    sh_xform(0, CARD_EX);
}

async sub at_ring(color: int, n: int, until: int) {
    emit_ring(color, n);
    var base: angle = rand(65536) as angle; // source %RANDRAD, full circle
    loop {
        if $frame >= until { return; }
        sh_angle(0, base, 0deg);
        sh_fire(0);
        base = base + 783bam; // source %A += %F0 = 0.075049rad
        wait(20);
    }
}

sub at2_ring(color: int, n: int, until: int) {
    emit_ring(color, n);
    var base: angle = rand(65536) as angle; // independent %RANDRAD
    loop {
        if $frame >= until { return; }
        sh_angle(0, base, 0deg);
        sh_fire(0);
        var u: int = rand(1566); // source %A -= %F0*%RANDF*2.0
        base = base - (u as angle);
        wait(20);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var t0: int = $frame;
    var until: int = t0 + SOURCE_LIMIT;
    // Source T0: clear old motion, then movePosTime(60,4,0,128).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(140);
    // Source moveLimit(0,128,280,96). The only later motion (moveRand) sits behind
    // the never-returning at2 loop, so the boss stays at (0,128), inside the limit.
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 12;
    if rank == 1 { n = 24; }
    if rank == 2 { n = 24; }
    if rank == 3 { n = 30; }
    // Source starts at async and at2 synchronously in the same frame; spawned task
    // first runs next frame, matching the source async call stack.
    spawn at_ring(2, n, until);
    at2_ring(6, n, until); // source at2 has 40000 rounds, never returns before timeout
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // source setHitbox(48,48): ordinary circle takes width*0.5
    set_hurtbox(24fx); // source setHurtbox(48,48)
    phase_begin(0, pattern, TIME_LIMIT, 5700); // source interrupt H5700/2100 -> BossCard3
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 144fx, 15700, 0, 0, 0, boss_main);
    loop { wait(600); }
}
